   Imports
   ========================================= */

/* =========================================
   Global Styles & Typography
   ========================================= */
h2, p {
    color: var(--primary-text-color);
    text-align: center;
}

.italic {
    font-style: italic;
}

.highlight {
    color: var(--highlight-color);
    font-weight: bold;
}

.softwareattributes {
    font-style: italic;
    color: rgb(160, 160, 160);
}

.proficiency {
    font-weight: bold;
    font-size: 0.9em;
    color: var(--highlight-color);
}

/* =========================================
   Headings
   ========================================= */
h3, .info h3 {
    border-radius: 5px;
    overflow: hidden;
    color: var(--primary-text-color);
    background: linear-gradient(135deg, var(--h3-background-color), var(--h3-background-color2));
    backdrop-filter: blur(10px);
    margin-right: auto;
    margin-bottom: 1.0vw;
    padding: 5px 5px 5px 0.5vw;
    text-decoration: none;
}

.info h3 {
    font-size: 1.1em;
}

.info h4 {
    color: var(--main-text-color);
    backdrop-filter: blur(10px);
    margin-left: 1vw;
    margin-right: auto;
    padding: 5px;
}

.section h1, .section a {
    color: var(--primary-text-color);
    text-decoration: none;
}

.section h1 {
    color: var(--tertiary-text-color);
    font-size: 1.3em;
    text-decoration: underline;
    text-decoration-color: rgba(180, 180, 180, 0.616);
    margin: 0px;
    background: linear-gradient(-10deg, var(--main-background-color4), var(--main-background-color3));
}

.section h1 img {
    padding-left: 10px;
    opacity: 0.3;
    width: clamp(25px, 25px, 25px);
    height: auto;
}

/* =========================================
   Containers & Layout
   ========================================= */

.section {
    background: linear-gradient(135deg, var(--section-color1), var(--section-color2));
    backdrop-filter: blur(10px);
    border-radius: 5px;
    box-shadow: 0px 4px 6px var(--box-shadow-color);
    padding-bottom: 0.2vw;
    margin-top: 15px;
}

.info {
    margin-top: 1vw;
    background: linear-gradient(135deg, rgba(146, 146, 146, 0.2), rgba(63, 63, 63, 0));
    backdrop-filter: blur(10px);
    border-radius: 5px;
    margin-left: auto;
    margin-right: auto;
    padding: 5px;
}

.info h1 {
    background: rgba(68, 68, 68, 0.479);
    padding: 5px;
    text-align: center;
    margin-left: auto;
    margin-right: auto;
    border-radius: 5px;
}

.info a {
    color: rgb(255, 255, 255);
}

.info video {
    width: 100%;
    height: auto;
    object-fit: cover;
}

.info h3{
    color: rgb(29, 29, 29);
    background: linear-gradient(135deg, var(--h3-background-color3),rgb(207, 207, 207));
}

.info img{
    margin-left: 1vw;
}

.list {
    background: linear-gradient(135deg, var(--section-color1), var(--section-color2));
    backdrop-filter: blur(10px);
    border-radius: 5px;
    box-shadow: 0px 4px 6px var(--box-shadow-color);
}

/* =========================================
   Lists
   ========================================= */

ol, ul {
    margin-block-start: 0;
    margin-block-end: 0;
}

h1 img{
    width: clamp(20px, 25px, 30px);
    height: auto;
    opacity: 0.3;
}

ol {
    color: var(--highlight-color);
}

button{
    margin-top: 1vw;
}

.numlist, .bulletlist {
    padding-top: 0;
padding-bottom: .5vw;   
    max-width: 83%;
}
.numlist li::marker, .bulletlist li::marker {
    color: var(--highlight-color);
}

.list li, .numlist li {
    margin: 5px 0;
    color: var(--primary-text-color);
}

.info ol li, .info ul li {
    font-size: 0.9em;
    color: var(--primary-text-color);
    margin-bottom: 0.5vw;
    margin-left: 0;
}

.languages .numlist {
    display: grid;
    grid-template-columns: repeat(4, 1fr); 
    gap: 1ex; 
    margin-left: 0;

    list-style-position: inside;
    max-width: 90%;
}

@media (max-width: 700px) {
    .languages .numlist {
        grid-template-columns: repeat(3, 1fr);
    }
}

@media (max-width: 500px) {
    .languages .numlist {
        grid-template-columns: repeat(2, 1fr);
    }
}

.languages .numlist li {
    margin-bottom: 1vw;
    margin-left: 0.5vw;
    break-inside: avoid-column;
}

.languages .numlist li:last-child {
    margin-bottom: 0;
}

/* =========================================
   Projects & Contests
   ========================================= */

.projects {
    width: clamp(200px, 95%, 800px);
}

.contests {
    display: flex;
    flex-direction: column;
}

.projects, .contests, .assignments {
    color: var(--main-text-color);
    text-decoration: none;
}

.projects h4, .assignments h4, .contests h4 {
    margin-top: 0vw;
    margin-bottom: 1vw;
    margin-left: 1vw;
    padding-left: 15px;
    max-width: 95%;
    font-size: 1em;
    font-weight: 500;
    color: var(--main-text-color);
    text-decoration: none;
    
}

.contest a, .contest h4 {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: clamp(200px, 100%, 900px);
    text-decoration: none;
    box-sizing: border-box;
    position: relative;
}

.contest_info {
    flex: 2 1 0;
    min-width: 55%;
    max-width: 95%;
    padding-right: 3vw;
    text-align: left;

}

.project_info {
    color: var(--highlight-color);
}

.rank, .rating {
    line-height: normal;
    align-self: center;
    height: auto;
    display: flex;
    align-items: center;
    padding-right: 1vw;
}

.rank {
    text-align: left;
    min-width: 65%;
    flex: 1;
    color: var(--highlight-color2);
}

.rating {
    flex: 1;
    min-width: 20%;
    color: var(--highlight-color3);
    width: fit-content;
    padding-left: 2vw;
    text-decoration-style: dashed;
    font-size: 10px;
}

.rank b, .rating b {
    margin-left: 5px;
    margin-right: 5px;
    font-weight: 800;
    color: var(--primary-text-color);
}

.problems {
    color: var(--highlight-color3);
    font-size: 13px;
    padding-left: 0.25vw;
}

/* Hover States & Links */

.assignments a, .project-link {
    text-decoration: none;
    color: inherit;
}

.contest:hover, .assignments a:hover, .project-link:hover, .titles a:hover, .info a:hover {
    text-decoration: underline;
    text-decoration-color: var(--highlight-color);
}

.section h1:hover, .section a:hover {
    text-decoration: underline;
    color: var(--link-hover-color);
    text-decoration-color: var(--mobile-underline-color);
}

/* =========================================
   Media Queries
   ========================================= */

/* Desktop Extra Large */
@media (min-width: 1440px) {
    .rank { min-width: 35%; }
    .contest_info { min-width: 55%; }
}

/* Tablet / Desktop Overrides */
@media (min-width: 768px) {
    .section a:hover {
        text-decoration: underline;
        text-decoration-color: var(--mobile-underline-color);
    }
}

/* Mobile Devices */
@media (max-width: 700px) {
    .section { padding-bottom: 1vw; }
    
    .section h3, .info h3 { 
        margin-bottom: 2vw; 
    }
    
    .contest_info { min-width: 50%; }
    
    .contest .project_info, .highlight, .section a:hover, .homepage a {
        text-decoration: underline;
        text-decoration-color: var(--mobile-underline-color);
    }
    
    .rank {
        margin-left: 10px;
        min-width: 40%;
        display: flex;
        flex-wrap: wrap;
        text-align: left;
        flex: 1;
        width: auto;
        overflow-wrap: break-word;
    }
    
    .projects h4, .assignments h4, .contests h4 {
        margin-top: 0vw;
        font-size: 0.9em;
        margin-left: 3vw;
        max-width: 90%;
    }
    
    .section .numlist, .section .bulletlist {
        font-size: 0.97em;
        margin-left: 0px;
    }
}

/* Small Mobile Devices */
@media (max-width: 500px) {
    .languages .numlist {
        column-count: 2;
        column-gap: 1ex;
    }
}`, "",{"version":3,"sources":["webpack://./css/styles.css"],"names":[],"mappings":"AAAA;;8CAE8C;;AAI9C;;8CAE8C;AAC9C;IACI,gCAAgC;IAChC,kBAAkB;AACtB;;AAEA;IACI,kBAAkB;AACtB;;AAEA;IACI,6BAA6B;IAC7B,iBAAiB;AACrB;;AAEA;IACI,kBAAkB;IAClB,yBAAyB;AAC7B;;AAEA;IACI,iBAAiB;IACjB,gBAAgB;IAChB,6BAA6B;AACjC;;AAEA;;8CAE8C;AAC9C;IACI,kBAAkB;IAClB,gBAAgB;IAChB,gCAAgC;IAChC,4FAA4F;IAC5F,2BAA2B;IAC3B,kBAAkB;IAClB,oBAAoB;IACpB,0BAA0B;IAC1B,qBAAqB;AACzB;;AAEA;IACI,gBAAgB;AACpB;;AAEA;IACI,6BAA6B;IAC7B,2BAA2B;IAC3B,gBAAgB;IAChB,kBAAkB;IAClB,YAAY;AAChB;;AAEA;IACI,gCAAgC;IAChC,qBAAqB;AACzB;;AAEA;IACI,iCAAiC;IACjC,gBAAgB;IAChB,0BAA0B;IAC1B,iDAAiD;IACjD,WAAW;IACX,iGAAiG;AACrG;;AAEA;IACI,kBAAkB;IAClB,YAAY;IACZ,8BAA8B;IAC9B,YAAY;AAChB;;AAEA;;8CAE8C;;AAE9C;IACI,iFAAiF;IACjF,2BAA2B;IAC3B,kBAAkB;IAClB,+CAA+C;IAC/C,qBAAqB;IACrB,gBAAgB;AACpB;;AAEA;IACI,eAAe;IACf,kFAAkF;IAClF,2BAA2B;IAC3B,kBAAkB;IAClB,iBAAiB;IACjB,kBAAkB;IAClB,YAAY;AAChB;;AAEA;IACI,mCAAmC;IACnC,YAAY;IACZ,kBAAkB;IAClB,iBAAiB;IACjB,kBAAkB;IAClB,kBAAkB;AACtB;;AAEA;IACI,yBAAyB;AAC7B;;AAEA;IACI,WAAW;IACX,YAAY;IACZ,iBAAiB;AACrB;;AAEA;IACI,sBAAsB;IACtB,mFAAmF;AACvF;;AAEA;IACI,gBAAgB;AACpB;;AAEA;IACI,iFAAiF;IACjF,2BAA2B;IAC3B,kBAAkB;IAClB,+CAA+C;AACnD;;AAEA;;8CAE8C;;AAE9C;IACI,qBAAqB;IACrB,mBAAmB;AACvB;;AAEA;IACI,8BAA8B;IAC9B,YAAY;IACZ,YAAY;AAChB;;AAEA;IACI,6BAA6B;AACjC;;AAEA;IACI,eAAe;AACnB;;AAEA;IACI,cAAc;AAClB,oBAAoB;IAChB,cAAc;AAClB;AACA;IACI,6BAA6B;AACjC;;AAEA;IACI,aAAa;IACb,gCAAgC;AACpC;;AAEA;IACI,gBAAgB;IAChB,gCAAgC;IAChC,oBAAoB;IACpB,cAAc;AAClB;;AAEA;IACI,aAAa;IACb,qCAAqC;IACrC,QAAQ;IACR,cAAc;;IAEd,2BAA2B;IAC3B,cAAc;AAClB;;AAEA;IACI;QACI,qCAAqC;IACzC;AACJ;;AAEA;IACI;QACI,qCAAqC;IACzC;AACJ;;AAEA;IACI,kBAAkB;IAClB,kBAAkB;IAClB,0BAA0B;AAC9B;;AAEA;IACI,gBAAgB;AACpB;;AAEA;;8CAE8C;;AAE9C;IACI,+BAA+B;AACnC;;AAEA;IACI,aAAa;IACb,sBAAsB;AAC1B;;AAEA;IACI,6BAA6B;IAC7B,qBAAqB;AACzB;;AAEA;IACI,eAAe;IACf,kBAAkB;IAClB,gBAAgB;IAChB,kBAAkB;IAClB,cAAc;IACd,cAAc;IACd,gBAAgB;IAChB,6BAA6B;IAC7B,qBAAqB;;AAEzB;;AAEA;IACI,aAAa;IACb,8BAA8B;IAC9B,mBAAmB;IACn